import json
from pathlib import Path
A=[]
def add(i,s,q,m,c='material',**kw): A.append(dict(index=i,classification=c,summary=s,rows=[dict(quote=q,model_quantity=m,stage='recognized',issuer_treatment=s,**kw)]))
add(392,'MSD juin : levée effectivement appelée 225 M$ le 26 juin, cumul 3,174988 Md$ contre 2,949988 Md$ en mars. Engagements ~3,6 Md$ dont 386,5 M$ non appelés, distincts du cash. Distributions H1 157,933 M$/1,14 par action incluent T1 78,799 et T2 79,134 ; DRP H1 28,093 M$ dont T2 14,175, non flux à ajouter comme levée primaire indépendante. Cumul DRP 386,614 M$ ne réduit pas engagements.','Shares issued under the DRP will not reduce outstanding Capital Commitments.','msd_q2_actual_225m_capital_drawdown')
add(393,'MSD juin : NAV/action 23,48 contre 23,71 décembre/23,58 mars ; NII H1 1,17 couvre distribution comptable 1,14, sans preuve de couverture cash compte tenu du PIK. Net assets 3,498843 Md$ augmentent avec levée 225 M$ malgré recul NAV/action ; ne pas qualifier hausse organique seule. Couverture 200,8 % remonte de 189,5 % mars, minimum 150 %. Engagements 3,561497 Md$, contribué 89,15 %, dette moyenne 3,549769 Md$ distincts des soldes.','Asset coverage ratio','msd_q2_coverage_recovery_after_equity_raise')
add(394,'MSD : amendement revolver du 30 juillet, post-juin, capacité engagée 670→920 M$, accordion conditionnel 675→1380 M$, maturité novembre 2029→30 juillet 2031 ; ne pas conserver l’ancienne échéance dans l’état actuel, ni assimiler nouvelles capacités à cash tiré. Investissements NewLevel IV/Palletforce post-juin sans montant ni lien IA fourni.','extend the maturity date from November 19, 2029 to July 30, 2031.','msd_post_june_revolver_extension')
add(395,'MSD juin : portefeuille et cash FV 7,084062 Md$, L3 6,103476 Md$/86,16 %, cash 226,255 M$, portefeuille seul 6,857807 Md$ calculé sans cash. Achats L3 H1 1,351349 Md$ incluent PIK, T2 516,634 M$ ; pas cash primaire. Roll-forward H1 ne se déduit pas par addition des trimestres avec transferts mesurés au début de chaque période. Footnote annonce zéro transfert L3→L2 H1 mais table −183,703 M$ et T1 deux transferts : discordance source conservée sans réécriture. Dépréciation L3 H1 −46,512 M$ ; aucune attribution entière IA. Prix dette sélectionnée FV 1,542240 Md$ vs principal 1,55 Md$, autres dettes exclues.','there were two and zero investments, respectively, that were transferred from Level 3 to Level 2','msd_h1_level3_rollforward_disclosure_discordance',judgment_sensitive=True)
add(396,'MSD juin : principal 3,494 Md$, bilan 3,431699 Md$, inutilisé 711 M$. Revolver tiré 100 M$ contre 580 mars et 160 décembre ; capacité bilan 670 M$ avant amendement juillet. Nouvelles notes 300 M$ émises 12 juin, échéance 12 juin 2029, 6,375 % cash semestriel ; swap reçoit fixe/paye SOFR+2,353 %, pas PIK. Dette tiers CLO 390 M$, Class C/preferred internes éliminés ; passage qui nomme CLO « 2030 Notes » tout en le faisant mûrir en 2035 doit être distingué des vraies notes unsecured 500 M$/mai 2030. Intérêts H1 115,855 M$ incluent T2 59,001 et composants noncash ; pas somme à nouveau.','The 2029 Notes are direct unsecured obligations of the Company.','msd_q2_new_notes_and_revolver_reduction')
add(397,'MSD juin : confirme explicitement BDC privée indéfiniment, SPV I/II/CLO I consolidés et mêmes objectifs, engagements investisseurs sur avis de tirage. Portefeuille initial secondaire affilié ; société parent BDT & MSD et restructuration conseil ne prouvent pas injection IA. Préférentielles 12 % entièrement remboursées décembre 2025 ; ni stock courant ni future sortie obligatoire au titre de l’ancien terme de cinq ans.','remain a privately offered BDC indefinitely.','msd_q2_private_indefinite_term_and_internal_spvs',c='context')
Path(__file__).with_suffix('.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
M=json.loads(Path('work/continuation398/scope.json').read_text())['rows']
for a in A:
    t=json.loads(Path(M[a['index']]['path']).read_text())['text']
    for r in a['rows']: assert r['quote'] in t,(a['index'],r['quote'])
